interface.definition:
a!localVariables(
  local!oldNominationStatus: a!refreshVariable(
    value: ri!nomination.statusId,
    refreshOnReferencedVarChange: false
  ),
  #"SYSTEM_SYSRULES_ButtonWidget"(
  label: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155707",
  value: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155707",
  saveInto: {
    ri!action,
    /*TASK CREATION AND EDIT*/
    if(
      ri!isEdit,
      /*Nomination task is already generated*/
      {
        a!save(
          ri!task.statusId,
          if(
            ri!nextStatusId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578354",
            #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3924800",
            ri!nextStatusId
          )
        ),
        a!save(
          ri!task.isCompleted,
          or(
            ri!nomination.isDirectHire = true,
            ri!isComplete = true
          )
        ),
        a!save(
          ri!task.assigneeId,
          if(
            ri!isComplete,
            null,
            if(
              ri!nextStatusId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578354",
              #"_a-0000e7e4-4b4e-8000-9c1d-011c48011c48_6307911",
              index(ri!assignee,"assigneeId",null)
            )
          )
        ),
        a!save(
          ri!task.isAssigneeGroup,
          if(
            ri!isComplete,
            false,
            if(
              ri!nextStatusId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578354",
              true,
              index(ri!assignee,"isAssigneeGroup",null) 
            )
          )
        ),
        a!save(ri!task.modifiedBy,ri!fullName),
        a!save(ri!task.modifiedOn,now())
      },
      /*Just initiated from the related action*/
      a!save(
        ri!task,
        'type!{urn:com:appian:types:CAW}CAW_Task'(
          moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164394",
          statusId: if(
            ri!nextStatusId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578354",
            #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3924800",
            ri!nextStatusId
          ),
          isCompleted: or(
            ri!nomination.isDirectHire = true,
            ri!isComplete = true
          ),
          assigneeId: if(
            ri!isComplete,
            null,
            if(
              ri!nextStatusId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578354",
              #"_a-0000e7e4-4b4e-8000-9c1d-011c48011c48_6307911",
              index(ri!assignee,"assigneeId",null)
            )
          ),
          isAssigneeGroup: if(
            ri!isComplete,
            false,
            if(
              ri!nextStatusId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578354",
              true,
              index(ri!assignee,"isAssigneeGroup",null) 
            )
          ),
          isLocked: false,
          isTaskAmend: false,
          version: 1,
          createdBy: ri!fullName,
          createdOn: now(),
          modifiedBy: ri!fullName,
          modifiedOn: now()
        )
      )
    ),
    /*NOMINATION UPDATES*/
    if(
      ri!isEdit,   
      null,
      {
        a!save(ri!nomination.fiscalYear,#"_a-0000e6d2-8270-8000-9c03-011c48011c48_3953700"()),
        a!save(ri!nomination.isActive,true),
        a!save(ri!nomination.createdBy,loggedInUser()),
        a!save(ri!nomination.createdOn,now()),
        if(
          ri!nomination.nominationTypeId = #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3868562",
          a!save(ri!nomination.positionTypeId,#"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699"),
          null
        ),
        if(
          isusermemberofgroups(
            loggedInUser(),
            #"_a-0000e825-ace1-8000-9c24-011c48011c48_6790160"
          ),
          a!save(
            ri!nomination.isNonAuditLeader,
            true
          ),
          a!save(
            ri!nomination.isNonAuditLeader,
            false
          )
        )
      }
    ),
    /*Interview Availability Updates*/
    if(
      ri!nomination.statusId = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458889",
      {
        a!save(ri!nomination.isInterviewAvailabilityCompleted,true),
        a!save(ri!nomination.isInterviewAvailabilityRequested,null)
      },
      if(
        ri!nomination.statusId = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458932",
        {
          a!save(ri!nomination.isOfficeVisitAvailabilityCompleted,true),
          a!save(ri!nomination.isOfficeVisitAvailabilityRequested,null)
        },
        null
      )
    ),
    /*Update In Review - HR Completed flags when current status is In Review - HR*/
    if(
      ri!nomination.statusId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4489118",
      {
        a!save(ri!nomination.isHRReviewCompleted,true),
        a!save(ri!nomination.hrReviewCompletedDate,now()),
        a!save(ri!nomination.isHRReview,null)
      },
      null
    ),
    /*Update In Review - Inspections Completed flags when current status is In Review - Inspections*/
    if(
      ri!nomination.statusId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4494074",
      {
        a!save(ri!nomination.isInspectionsReviewCompleted,true),
        a!save(ri!nomination.inspectionReviewCompletedDate,now()),
        a!save(ri!nomination.isInspectionsReview,null)
      },
      null
    ),
    /*Direct Hire Nomination Completed*/
    if(
      ri!nomination.isDirectHire = true,
      a!save(ri!nomination.isReadyForOnboarding, true),
      null
    ),
    /*is additional follow up required completed field logic*/
    if(
      and(
        ri!nomination.isAdditionalFollowUpReq = true,
        #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.isAdditionalFollowUpReqCompleted),
      ),
      a!save(ri!nomination.isAdditionalFollowUpReqCompleted,true),
      null
    ),
    a!save(ri!nomination.statusId,ri!nextStatusId),
    a!save(ri!nomination.modifiedBy,ri!fullName),
    a!save(ri!nomination.modifiedOn,now()),
    /* Audit History */
    a!save(
      ri!auditHistory,
      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4948093"(
        isComplete: ri!isComplete,
        task: ri!task,
        nomination: ri!nomination,
        currentNominationStatus: local!oldNominationStatus
      )
    ),
    /*COMMENT LOGIC*/
    a!save(
      ri!comment,
      'type!{urn:com:appian:types:CAW}CAW_Comment'(
        commentId: ri!comment.commentId,
        requestId: ri!nomination.nominationId,
        moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164394",
        comment: ri!comment.comment,
        isDraft: false,
        isActive: true,
        version: 1,
        createdBy: if(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!comment.createdBy),loggedInUser(),ri!comment.createdBy),
        createdOn: if(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!comment.createdOn),now(),ri!comment.createdOn),
        modifiedBy: loggedInUser(),
        modifiedOn: now()
      )
    ),

  },
  submit: true,
  showWhen: ri!showWhen,
  disabled: ri!disabled,
  confirmHeader: "Submit",
  validationGroup: "main",
  confirmMessage: #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5116210"(
    isComplete: ri!isComplete,
    task: ri!task,
    nomination: ri!nomination,
    isBasicApproval: ri!isBasicApproval
  ),
  style: "PRIMARY",
  tooltip: "Please fill all required fields"
)
)
